#!/bin/bash
sed -i 's/<button onClick={() => navigate('"'"'\/profile'"'"')} className={`flex flex-col items-center justify-center w-full h-full gap-1 transition-colors ${activeMobileTab === '"'"'orders_tab'"'"' ? '"'"'text-blue-500'"'"' : (isDarkMode ? '"'"'text-zinc-500 hover:text-zinc-300'"'"' : '"'"'text-zinc-400 hover:text-zinc-600'"'"')}`}>/<button onClick={() => navigate(user.email === '"'"'damijosh12@gmail.com'"'"' ? '"'"'\/admin'"'"' : '"'"'\/profile'"'"')} className={`flex flex-col items-center justify-center w-full h-full gap-1 transition-colors ${activeMobileTab === '"'"'orders_tab'"'"' || activeMobileTab === '"'"'admin'"'"' ? '"'"'text-blue-500'"'"' : (isDarkMode ? '"'"'text-zinc-500 hover:text-zinc-300'"'"' : '"'"'text-zinc-400 hover:text-zinc-600'"'"')}`}>/g' src/Store.tsx

sed -i 's/<Package className={`w-5 h-5 ${activeMobileTab === '"'"'orders_tab'"'"' ? '"'"'fill-blue-500\/20'"'"' : '"'"''"'"'}`} \/>/{user.email === '"'"'damijosh12@gmail.com'"'"' ? <LayoutDashboard className={`w-5 h-5 ${activeMobileTab === '"'"'admin'"'"' ? '"'"'fill-blue-500\/20'"'"' : '"'"''"'"'}`} \/> : <Package className={`w-5 h-5 ${activeMobileTab === '"'"'orders_tab'"'"' ? '"'"'fill-blue-500\/20'"'"' : '"'"''"'"'}`} \/>}/g' src/Store.tsx

sed -i 's/<span className="text-\[10px\] font-medium">Orders<\/span>/{user.email === '"'"'damijosh12@gmail.com'"'"' ? <span className="text-\[10px\] font-medium">Admin<\/span> : <span className="text-\[10px\] font-medium">Orders<\/span>}/g' src/Store.tsx
